  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "limit": {
      "type": "integer",
      "description": "Max entries to return (default 20)."
    }
  }
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The memory entry id (from memory_list/search)."
    },
    "scope": {
      "type": "string",
      "enum": [
        "project",
